import {depth} from './depth.mjs';
import {cases} from './cases.mjs';
const state={};
const add=(tag,text,host)=>{const e=document.createElement(tag);e.textContent=text;host.append(e);return e;};
export function renderDepth(lesson,track,lang){const t=(es,en)=>lang==='es'?es:en,root=document.querySelector('#reasoning');root.replaceChildren();add('h3',t('Razonar paso a paso','Reason it through'),root);const ol=add('ol','',root);for(const step of depth[lesson.id].steps)add('li',step[lang],ol);
 const host=document.querySelector('#workshopCase');host.hidden=lesson!==track.lessons.at(-1);if(host.hidden)return;const c=cases[track.id],s=state[track.id]||(state[track.id]={step:0,choices:{},done:false});host.replaceChildren();add('p',t('CASO DE TALLER · PRÁCTICA SIN NOTA','WORKSHOP CASE · UNGRADED PRACTICE'),host).className='eyebrow';add('h3',c.title[lang],host);add('p',c.context[lang],host);
 if(s.done){add('p',c.conclusion[lang],host).className='case-conclusion';const btn=add('button',t('Repetir el caso','Repeat case'),host);btn.onclick=()=>{state[track.id]={step:0,choices:{},done:false};renderDepth(lesson,track,lang);};return;}
 const step=c.steps[s.step],choice=s.choices[s.step];add('p',t('Paso ','Step ')+(s.step+1)+' / '+c.steps.length,host);add('h4',t('Evidencia disponible','Available evidence'),host);add('p',step.evidence[lang],host).className='case-evidence';add('h4',step.question[lang],host);const opts=add('div','',host);opts.className='case-options';step.options.forEach((o,i)=>{const btn=add('button',o[lang],opts);btn.dataset.caseAnswer=i;btn.setAttribute('aria-pressed',String(choice===i));btn.disabled=choice===step.correct;btn.onclick=()=>{s.choices[s.step]=i;renderDepth(lesson,track,lang);};});const feedback=add('p',choice===undefined?'':step.why[choice][lang],host);feedback.id='caseFeedback';feedback.setAttribute('role','status');const next=add('button',s.step===c.steps.length-1?t('Ver conclusión','See conclusion'):t('Ver siguiente evidencia','See next evidence'),host);next.dataset.caseNext='';next.disabled=choice!==step.correct;next.onclick=()=>{if(s.choices[s.step]!==step.correct)return;if(s.step===c.steps.length-1)s.done=true;else s.step++;renderDepth(lesson,track,lang);};add('p',t('El caso conserva tus elecciones al cambiar de idioma durante esta visita. No modifica la nota ni simula estos fallos en el banco 3D.','The case preserves your choices when switching language during this visit. It does not change your score or simulate these faults in the 3D bench.'),host).className='note';
}
